function validate([s1, s2]) {
  if (typeof s1 !== 'string' || typeof s2 !== 'string') return 's1 and s2 must be strings.';
  if (s1.length < 1 || s1.length > 30) return 's1 has 1 to 30 characters.';
  if (s1.length !== s2.length) return 's1 and s2 must have the same length.';
  if (!/^[a-z]*$/.test(s1) || !/^[a-z]*$/.test(s2)) return 'Use lowercase English letters only.';
  return null;
}

