function isScramble(s1, s2) {
  const n = s1.length;
  const dp = Array.from({ length: n + 1 }, () => Array.from({ length: n }, () => new Array(n).fill(false)));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      dp[1][i][j] = s1[i] === s2[j];
    }
  }
  for (let len = 2; len <= n; len++) {
    for (let i = 0; i + len <= n; i++) {
      for (let j = 0; j + len <= n; j++) {
        for (let k = 1; k < len; k++) {
          const keep = dp[k][i][j] && dp[len - k][i + k][j + k];
          const swap = dp[k][i][j + len - k] && dp[len - k][i + k][j];
          if (keep || swap) {
            dp[len][i][j] = true;
            break;
          }
        }
      }
    }
  }
  return dp[n][0][0];
}

