function isScramble(s1, s2) {
  const memo = new Map();
  const solve = (a, b) => {
    if (a === b) return true;
    if (a.length === 1) return false;
    const key = a + '|' + b;
    if (memo.has(key)) return memo.get(key);
    let ok = false;
    for (let cut = 1; cut < a.length && !ok; cut++) {
      const tail = a.length - cut;
      if (solve(a.slice(0, cut), b.slice(0, cut)) && solve(a.slice(cut), b.slice(cut))) ok = true;
      else if (solve(a.slice(0, cut), b.slice(tail)) && solve(a.slice(cut), b.slice(0, tail))) ok = true;
    }
    memo.set(key, ok);
    return ok;
  };
  return solve(s1, s2);
}

