function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const alphabets = ['ab', 'abc', 'abcd', 'abcdefghijklmnopqrstuvwxyz'];
  const n = size === 'large' ? int(24, 30) : int(1, 7);
  const word = (alphabet) => {
    let s = '';
    for (let k = 0; k < n; k++) s += alphabet[int(0, alphabet.length - 1)];
    return s;
  };
  const scramble = (s) => {
    if (s.length === 1) return s;
    const cut = int(1, s.length - 1);
    const x = scramble(s.slice(0, cut));
    const y = scramble(s.slice(cut));
    return rand() < 0.5 ? x + y : y + x;
  };
  const swapTwo = (s) => {
    const chars = s.split('');
    const a = int(0, n - 1), b = int(0, n - 1);
    [chars[a], chars[b]] = [chars[b], chars[a]];
    return chars.join('');
  };
  const shuffle = (s) => {
    const chars = s.split('');
    for (let k = chars.length - 1; k > 0; k--) {
      const r = int(0, k);
      [chars[k], chars[r]] = [chars[r], chars[k]];
    }
    return chars.join('');
  };
  // Plain scrambles are almost always true, so half the inputs retry until the answer is false.
  const memo = new Map();
  const scrambles = (a, b) => {
    if (a === b) return true;
    if ([...a].sort().join('') !== [...b].sort().join('')) return false;
    const key = a + '|' + b;
    if (memo.has(key)) return memo.get(key);
    let ok = false;
    for (let cut = 1; cut < a.length && !ok; cut++) {
      const tail = a.length - cut;
      ok = (scrambles(a.slice(0, cut), b.slice(0, cut)) && scrambles(a.slice(cut), b.slice(cut))) || (scrambles(a.slice(0, cut), b.slice(tail)) && scrambles(a.slice(cut), b.slice(0, tail)));
    }
    memo.set(key, ok);
    return ok;
  };
  if (rand() < 0.5) {
    const s1 = word(alphabets[int(0, alphabets.length - 1)]);
    return [s1, scramble(s1)];
  }
  for (let tries = 0; ; tries++) {
    const s1 = word(alphabets[int(1, alphabets.length - 1)]);
    const mode = rand();
    const s2 = mode < 0.6 ? shuffle(s1) : mode < 0.85 ? swapTwo(scramble(s1)) : word(alphabets[int(1, alphabets.length - 1)]);
    if (tries >= 40 || !scrambles(s1, s2)) return [s1, s2];
  }
}
